import {CHAT_HISTORY_LIMIT} from './world-chat-store.js?v=20261011-free-cook73';
export function createWorldChat({names,skinURL,makeFace,getSelfId,send,isConnected,onOpen,onClose}){
  const $=id=>document.getElementById(id),panel=$('worldChat'),history=$('chatHistory'),records=new Map();let nextCursor=null,pending=false,loading=false,terminal=false,latestTimer=0;
  function face(skin){const holder=document.createElement('span');holder.className='chat-face';makeFace(skinURL(skin),holder);return holder;}
  function messageNode(message){const row=document.createElement('article');row.className='chat-row';row.append(face(message.skin));const bubble=document.createElement('div');bubble.className='chat-bubble';const meta=document.createElement('div');meta.className='chat-meta';const name=document.createElement('strong');name.textContent=names[message.skin]||'ゲスト';const date=document.createElement('time');date.dateTime=new Date(message.at).toISOString();date.textContent=new Date(message.at).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});meta.append(name,date);const body=document.createElement('p');body.textContent=message.text;bubble.append(meta,body);row.append(bubble);return row;}
  function render(toBottom=false){const previousHeight=history.scrollHeight,previousScroll=history.scrollTop;history.replaceChildren(...[...records.values()].sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id)).map(messageNode));$('chatOlder').hidden=nextCursor===null;$('chatOlder').disabled=loading;$('chatEmpty').hidden=records.size>0;if(toBottom)history.scrollTop=history.scrollHeight;else history.scrollTop=previousScroll+history.scrollHeight-previousHeight;}
  function showLatest(message){const top=$('chatLatest');clearTimeout(latestTimer);const remaining=30000-(Date.now()-message.at);if(remaining<=0){top.hidden=true;return;}top.replaceChildren(messageNode(message));top.hidden=false;latestTimer=setTimeout(()=>{top.hidden=true;},remaining);}
  function prune(page){for(const [id,message]of records)if(page?.oldestAt&&(message.at<page.oldestAt||message.at===page.oldestAt&&id.localeCompare(page.oldestId)<0))records.delete(id);const ordered=[...records.values()].sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id));for(const message of ordered.slice(0,Math.max(0,ordered.length-CHAT_HISTORY_LIMIT)))records.delete(message.id);}
  function ingest(page){prune(page);for(const message of page?.messages||[])records.set(message.id,message);prune(page);nextCursor=page?.nextCursor??null;loading=false;render(false);}
  function open(page){terminal=true;onOpen();panel.hidden=false;document.body.dataset.chatting='true';if(page)ingest(page);render(true);$('chatInput').focus();$('chatStatus').textContent=isConnected()?'ワールドにメッセージを残せます':'サーバー接続が必要です';}
  function close(){panel.hidden=true;terminal=false;document.body.dataset.chatting='false';onClose();}
  function older(){if(loading||nextCursor===null||!isConnected())return;loading=true;$('chatOlder').disabled=true;send({type:'chat-history',before:nextCursor});}
  $('chatOlder').onclick=older;history.addEventListener('scroll',()=>{if(history.scrollTop<20)older();});$('closeWorldChat').onclick=close;
  $('chatForm').onsubmit=event=>{event.preventDefault();const text=$('chatInput').value.trim();if(!text||pending)return;if(!isConnected()||!terminal){$('chatStatus').textContent='サーバーに接続してから送信してください';return;}pending=true;$('chatSend').disabled=true;$('chatStatus').textContent='保存中…';send({type:'chat-post',text});};
  $('chatInput').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();$('chatForm').requestSubmit();}});
  return {get active(){return !panel.hidden;},open,close,hydrate(page){records.clear();ingest(page);const latest=[...records.values()].sort((a,b)=>a.at-b.at).at(-1);if(latest)showLatest(latest);else $('chatLatest').hidden=true;},receive(message){if(message.type==='chat-message'&&message.scope==='world'){const atBottom=history.scrollHeight-history.scrollTop-history.clientHeight<80;records.set(message.message.id,message.message);prune(message);showLatest(message.message);if(!panel.hidden)render(atBottom);if(message.authorId===getSelfId()){pending=false;$('chatSend').disabled=false;$('chatInput').value='';$('chatStatus').textContent='ワールドに保存しました';}return true;}if(message.playerId!==getSelfId())return false;if(message.type==='chat-open'){open(message);return true;}if(message.type==='chat-history'){ingest(message);return true;}if(message.type==='chat-error'){pending=false;$('chatSend').disabled=false;$('chatStatus').textContent=message.message;return true;}return false;},disconnected(){pending=false;loading=false;$('chatSend').disabled=false;if(!panel.hidden)$('chatStatus').textContent='接続が切れました。再接続後にチャットを開き直してください';terminal=false;},key(event){if(panel.hidden)return false;if(event.code==='Escape'){event.preventDefault();close();}return true;}};
}
